private void appendTree(Node node, int space, StringBuilder output) {
    if (node == null) {
        return;
    }

    space += PRINT_INDENT;
    appendTree(node.right, space, output);

    output.append('\n');

    for (int i = PRINT_INDENT; i < space; i++) {
        output.append(' ');
    }

    output.append(node.data).append('\n');
    appendTree(node.left, space, output);
}

